"""In-process vulnerability alert exemptions for registered resources.

An exemption records that one specific alert — identified byte-for-byte
by its advisory identifier and component name — is deliberately waived
for a resource, together with a free-form reason. Exemptions are kept
per resource in registration order and are never persisted: stopping or
restarting the service clears every exemption, and no files are
written. Exemptions only affect the admission preview; the admission
evaluation itself and every other readout keep counting all alerts.
"""

from __future__ import annotations

import uuid
from dataclasses import dataclass

#: Fields accepted by the registration request; anything else is rejected.
_ALLOWED_FIELDS = frozenset({"advisory", "component", "reason"})
_REQUIRED_FIELDS = ("advisory", "component", "reason")


class VulnerabilityExceptionValidationError(ValueError):
    """An exemption payload failed field-level validation."""

    def __init__(self, message: str) -> None:
        super().__init__(message)
        self.message = message


class VulnerabilityExceptionError(ValueError):
    """An exemption operation could not proceed.

    ``code`` is the stable, client-facing error code.
    """

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


@dataclass(frozen=True, slots=True)
class VulnerabilityException:
    """A single exemption recorded against a resource's alert."""

    id: str
    advisory: str
    component: str
    reason: str

    def to_dict(self) -> dict[str, object]:
        return {
            "id": self.id,
            "advisory": self.advisory,
            "component": self.component,
            "reason": self.reason,
        }


def build_exception_fields(payload: object) -> tuple[str, str, str]:
    """Validate a decoded JSON payload and return the field values.

    Returns ``(advisory, component, reason)``; all three are required
    non-empty strings and are kept verbatim (no trimming or folding).
    """

    if not isinstance(payload, dict):
        raise VulnerabilityExceptionValidationError(
            "Request body must be a JSON object."
        )

    unknown_fields = set(payload) - _ALLOWED_FIELDS
    if unknown_fields:
        raise VulnerabilityExceptionValidationError(
            f"Unknown field: {sorted(unknown_fields)[0]!r}."
        )

    for field in _REQUIRED_FIELDS:
        if field not in payload:
            raise VulnerabilityExceptionValidationError(
                f"Missing required field: {field!r}."
            )

    values: list[str] = []
    for field in _REQUIRED_FIELDS:
        value = payload[field]
        if not isinstance(value, str):
            raise VulnerabilityExceptionValidationError(
                f"Field {field!r} must be a string."
            )
        if not value:
            raise VulnerabilityExceptionValidationError(
                f"Field {field!r} must not be empty."
            )
        values.append(value)

    return values[0], values[1], values[2]


class VulnerabilityExceptionStore:
    """Process-local, registration-ordered exemption storage per resource."""

    def __init__(self) -> None:
        # resource id -> exemptions in registration order.
        self._records: dict[str, list[VulnerabilityException]] = {}

    def reset(self) -> None:
        self._records = {}

    def add(
        self, resource_id: str, advisory: str, component: str, reason: str
    ) -> VulnerabilityException:
        """Append an exemption for ``resource_id``.

        Raises :class:`VulnerabilityExceptionError` with code
        ``duplicate_exception`` when an exemption with the same advisory
        and component pair is already recorded for the resource; the
        original exemption is left untouched.
        """

        records = self._records.setdefault(resource_id, [])
        for record in records:
            if record.advisory == advisory and record.component == component:
                raise VulnerabilityExceptionError(
                    "duplicate_exception",
                    "An exemption with the same advisory and component "
                    "already exists for this resource.",
                )

        record = VulnerabilityException(
            id=uuid.uuid4().hex,
            advisory=advisory,
            component=component,
            reason=reason,
        )
        records.append(record)
        return record

    def list_for(self, resource_id: str) -> list[VulnerabilityException]:
        """Return a resource's exemptions in registration order."""

        return list(self._records.get(resource_id, ()))

    def exempted_keys(self, resource_id: str) -> set[tuple[str, str]]:
        """Return the (advisory, component) pairs exempted for a resource."""

        return {
            (record.advisory, record.component)
            for record in self._records.get(resource_id, ())
        }

    def remove(
        self, resource_id: str, exception_id: str
    ) -> VulnerabilityException:
        """Remove and return one exemption of ``resource_id``.

        Raises :class:`VulnerabilityExceptionError` with code
        ``exception_not_found`` when no exemption with that identifier is
        recorded for the resource (unknown or already deleted).
        """

        records = self._records.get(resource_id, [])
        for index, record in enumerate(records):
            if record.id == exception_id:
                del records[index]
                return record
        raise VulnerabilityExceptionError(
            "exception_not_found",
            "No exemption exists with the requested id.",
        )

